CREATE ROLE anon;CREATE ROLE authenticated;
CREATE SCHEMA auth;CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT NULL::uuid $$;
GRANT USAGE ON SCHEMA auth,public TO anon,authenticated;GRANT EXECUTE ON FUNCTION auth.uid() TO anon,authenticated;
CREATE TABLE users_master(id bigint PRIMARY KEY,full_name text,role text,is_active boolean);
CREATE TABLE user_permissions(user_id bigint,section_key text,is_allowed boolean);
CREATE TABLE materials(id bigint PRIMARY KEY,unit text,unit_cost numeric,gst_type text,gst_percentage numeric);
CREATE TABLE material_sales_prices(material_id bigint PRIMARY KEY,sales_price numeric,gst_type text,gst_percentage numeric);
CREATE TABLE material_requests(id bigint PRIMARY KEY,material_id bigint,ticket_no text,requested_qty numeric,approved_qty numeric,issued_qty numeric DEFAULT 0,request_status text,location_name text,location_type text,technician_name text);
CREATE TABLE material_issue_register(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,request_id bigint REFERENCES material_requests(id),material_id bigint,ticket_no text,issued_qty numeric,unit_cost numeric,total_cost numeric,remarks text,issued_by text,issued_date timestamptz DEFAULT now(),location_name text,location_type text,technician_name text);
CREATE TABLE stock_ledger(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,material_id bigint,transaction_type text,quantity numeric,reference_no text,request_id bigint,remarks text,created_by bigint,transaction_date timestamptz);
CREATE VIEW current_stock AS SELECT material_id,sum(CASE WHEN transaction_type='ISSUE' THEN -abs(quantity) ELSE quantity END) AS current_stock FROM stock_ledger GROUP BY material_id;
